def find_path(graph, start, goal, (x, x_f, x_p)=None, (gx, gy, x_p)=None, (x, x_f, x_p) - None, f = 0, x_gx = 0, x_p = None, x_p - None):
    if not isinstance(graph, dict) or not isinstance(start, str) or not isinstance(goal, str):
        raise ValueError("Graph must be a dict, start and goal must be strings.")

    if start not in graph or goal not in graph:
        raise ValueError("Start or goal must be in the graph.")

    visited = set()
    path_stack = [(start, [start])]

    while path_stack:
        node, path = path_stack.pop()

        if node not in visited:
            visited.add(node)
            if node == goal:
                return path
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    path_stack.append((neighbor, path + [neighbor]))

    return None

